package ec.edu.ucacue.odontocare.treatment.domain;
import java.time.*;import java.util.*;import ec.edu.ucacue.odontocare.clinicalrecord.domain.DentalConsultation;import ec.edu.ucacue.odontocare.odontogram.domain.DentalPiece;import jakarta.persistence.*;
@Entity @Table(name="dental_procedures") public class DentalProcedure{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="consultation_id")private DentalConsultation consultation;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="procedure_type_id")private ProcedureTypeCatalog type;@Column(name="diagnosis_id")private Long diagnosisId;private String name;private String description;@Column(name="material_used")private String materialUsed;@Column(name="anesthesia_used")private String anesthesiaUsed;@Column(name="post_instructions")private String postInstructions;@Enumerated(EnumType.STRING)private ProcedureStatus status;@Column(name="performed_at")private LocalDateTime performedAt;@Column(name="next_control_date")private LocalDate nextControlDate;@Column(name="created_by")private Long createdBy;
 @ManyToMany@JoinTable(name="dental_procedure_pieces",joinColumns=@JoinColumn(name="procedure_id"),inverseJoinColumns=@JoinColumn(name="dental_piece_id"))@OrderBy("visualOrder ASC")private Set<DentalPiece> pieces=new LinkedHashSet<>();protected DentalProcedure(){}
 public DentalProcedure(DentalConsultation c,ProcedureTypeCatalog t,Long diagnosisId,String description,String material,String anesthesia,String instructions,ProcedureStatus status,LocalDateTime date,LocalDate next,Long user,Set<DentalPiece> pieces){consultation=c;type=t;name=t.getName();this.diagnosisId=diagnosisId;this.description=description;materialUsed=material;anesthesiaUsed=anesthesia;postInstructions=instructions;this.status=status;performedAt=date;nextControlDate=next;createdBy=user;this.pieces.addAll(pieces);}
 public Long getId(){return id;}public DentalConsultation getConsultation(){return consultation;}public ProcedureTypeCatalog getType(){return type;}public Long getDiagnosisId(){return diagnosisId;}public String getDescription(){return description;}public String getMaterialUsed(){return materialUsed;}public String getAnesthesiaUsed(){return anesthesiaUsed;}public String getPostInstructions(){return postInstructions;}public ProcedureStatus getStatus(){return status;}public LocalDateTime getPerformedAt(){return performedAt;}public LocalDate getNextControlDate(){return nextControlDate;}public Long getCreatedBy(){return createdBy;}public Set<DentalPiece> getPieces(){return pieces;}
}
